INSERT INTO `farmer_profiles` (`farmer_id`, `stall_name`, `bio`, `farm_address`, `latitude`, `longitude`, `is_approved`, `created_at`, `updated_at`) VALUES
(1001, 'Trang Trại Trái Cây TP. Hồ Chí Minh - Sạp 01', 'Chuyên canh nông sản sạch tiêu chuẩn VietGAP tại TP. Hồ Chí Minh. Cam kết không thuốc trừ sâu, canh tác vi sinh hữu cơ tuần hoàn.', 'Khu nông nghiệp công nghệ cao số 3, tỉnh TP. Hồ Chí Minh', 10.828100, 106.634700, 1, NOW(), NOW()),
(1002, 'HTX Nông Sản Sạch Đà Nẵng - Sạp 02', 'Chuyên canh nông sản sạch tiêu chuẩn VietGAP tại Đà Nẵng. Cam kết không thuốc trừ sâu, canh tác vi sinh hữu cơ tuần hoàn.', 'Khu nông nghiệp công nghệ cao số 6, tỉnh Đà Nẵng', 16.064400, 108.212200, 1, NOW(), NOW()),
