INSERT INTO `reviews` (`review_id`, `order_id`, `customer_id`, `farmer_id`, `product_id`, `rating`, `comment`, `farmer_reply`, `farmer_reply_at`, `is_hidden`, `created_at`) VALUES
(1001, 1001, 2001, 1001, 1001, 4, 'Rau rất tươi non, đúng chuẩn hữu cơ hái sáng sớm tại vườn!', 'Dạ nhà vườn chân thành cảm ơn quý khách, mong tiếp tục được phục vụ gia đình mình ạ!', NOW(), 0, NOW()),
(1002, 1002, 2002, 1002, 1002, 5, 'Bưởi ngọt lịm tôm mọng nước, gia đình ai cũng khen ngợi.', 'Cảm ơn bạn nhiều nhé, lứa tới vườn có thêm dưa lưới hữu cơ mời bạn ghé ủng hộ.', NOW(), 0, NOW()),
(1003, 1003, 2003, 1003, 1003, 5, 'Nông sản đóng gói cẩn thận, bao bì sinh học thân thiện môi trường.', 'Nhà vườn cam kết luôn mang nông sản tươi ngon chuẩn sạch nhất đến tay khách hàng!', NOW(), 0, NOW()),
(1004, 1004, 2004, 1004, 1004, 5, 'Nông dân thân thiện, hướng dẫn nguồn gốc xuất xứ rất chi tiết.', 'Chúc bạn và gia đình thật nhiều sức khỏe với nguồn thực phẩm sạch xanh an lành!', NOW(), 0, NOW()),
(1005, 1005, 2005, 1005, 1005, 4, 'Chất lượng vượt trội so với siêu thị, ủng hộ bà con nông dân nhiệt tình!', 'Dạ nhà vườn chân thành cảm ơn quý khách, mong tiếp tục được phục vụ gia đình mình ạ!', NOW(), 0, NOW()),
(1006, 1006, 2006, 1006, 1006, 5, 'Đơn hàng soạn sẵn chỉ việc ghé sạp quét mã QR lấy luôn, cực kỳ tiện lợi.', 'Cảm ơn bạn nhiều nhé, lứa tới vườn có thêm dưa lưới hữu cơ mời bạn ghé ủng hộ.', NOW(), 0, NOW()),
(1007, 1007, 2007, 1007, 1007, 5, 'Cà chua bi ngọt thanh mọng nước, các bé nhà mình rất mê.', 'Nhà vườn cam kết luôn mang nông sản tươi ngon chuẩn sạch nhất đến tay khách hàng!', NOW(), 0, NOW()),
(1008, 1008, 2008, 1008, 1008, 5, 'Sầu riêng chín cây hạt lép thơm phức, đúng cam kết không hóa chất bảo quản!', 'Chúc bạn và gia đình thật nhiều sức khỏe với nguồn thực phẩm sạch xanh an lành!', NOW(), 0, NOW()),
(1009, 1009, 2009, 1009, 1009, 4, 'Rau rất tươi non, đúng chuẩn hữu cơ hái sáng sớm tại vườn!', 'Dạ nhà vườn chân thành cảm ơn quý khách, mong tiếp tục được phục vụ gia đình mình ạ!', NOW(), 0, NOW()),
