(1079, 1079, 2079, 1079, 1079, 5, 'Cà chua bi ngọt thanh mọng nước, các bé nhà mình rất mê.', 'Nhà vườn cam kết luôn mang nông sản tươi ngon chuẩn sạch nhất đến tay khách hàng!', NOW(), 0, NOW()),
(1080, 1080, 2080, 1080, 1080, 5, 'Sầu riêng chín cây hạt lép thơm phức, đúng cam kết không hóa chất bảo quản!', 'Chúc bạn và gia đình thật nhiều sức khỏe với nguồn thực phẩm sạch xanh an lành!', NOW(), 0, NOW()),
(1081, 1081, 2081, 1081, 1081, 4, 'Rau rất tươi non, đúng chuẩn hữu cơ hái sáng sớm tại vườn!', 'Dạ nhà vườn chân thành cảm ơn quý khách, mong tiếp tục được phục vụ gia đình mình ạ!', NOW(), 0, NOW()),
(1082, 1082, 2082, 1082, 1082, 5, 'Bưởi ngọt lịm tôm mọng nước, gia đình ai cũng khen ngợi.', 'Cảm ơn bạn nhiều nhé, lứa tới vườn có thêm dưa lưới hữu cơ mời bạn ghé ủng hộ.', NOW(), 0, NOW()),
(1083, 1083, 2083, 1083, 1083, 5, 'Nông sản đóng gói cẩn thận, bao bì sinh học thân thiện môi trường.', 'Nhà vườn cam kết luôn mang nông sản tươi ngon chuẩn sạch nhất đến tay khách hàng!', NOW(), 0, NOW()),
