INSERT INTO `system_announcements` (`announcement_id`, `admin_id`, `title`, `content`, `is_active`, `published_at`, `type`, `target_role`, `priority`) VALUES
(1001, 101, 'Thông báo lịch mở phiên chợ đặc biệt cuối tuần (Kỳ 1)', 'Phiên chợ nông sản sạch sẽ tăng cường 20 gian hàng đặc sản Tây Bắc và Tây Nguyên phục vụ cư dân. Kính gửi quý bà con nông dân và quý khách hàng cập nhật chi tiết tại cổng thông tin MarketLink.', 1, NOW(), 'EVENT', 'ALL', 'HIGH'),
(1002, 102, 'Khuyến khích sử dụng túi giấy và bao bì sinh học (Kỳ 2)', 'Hệ thống MarketLink tặng voucher giảm 10% cho khách hàng mang theo làn tre hoặc túi cá nhân khi nhận hàng. Kính gửi quý bà con nông dân và quý khách hàng cập nhật chi tiết tại cổng thông tin MarketLink.', 1, NOW(), 'GENERAL', 'CUSTOMER', 'NORMAL'),
(1003, 101, 'Cập nhật quy chuẩn chứng nhận kiểm định VietGAP 2026 (Kỳ 3)', 'Toàn bộ nông dân tham gia phiên chợ đã được Ban kiểm soát chất lượng thẩm tra định kỳ đạt kết quả tốt. Kính gửi quý bà con nông dân và quý khách hàng cập nhật chi tiết tại cổng thông tin MarketLink.', 1, NOW(), 'GENERAL', 'ALL', 'NORMAL'),
(1004, 102, 'Hỗ trợ trợ giá cước vận chuyển cho nhà vườn vùng xa (Kỳ 4)', 'Ban tổ chức áp dụng chính sách trợ giá 100% chi phí luân chuyển nông sản từ Mộc Châu về Hà Nội. Kính gửi quý bà con nông dân và quý khách hàng cập nhật chi tiết tại cổng thông tin MarketLink.', 1, NOW(), 'EVENT', 'FARMER', 'NORMAL'),
(1005, 101, 'Tọa đàm: Nông nghiệp tuần hoàn và kết nối chuỗi giá trị (Kỳ 5)', 'Thân mời các chủ hộ nhà vườn và khách hàng thân thiết tham gia buổi chia sẻ trực tuyến vào tối Thứ 5 tuần này. Kính gửi quý bà con nông dân và quý khách hàng cập nhật chi tiết tại cổng thông tin MarketLink.', 1, NOW(), 'GENERAL', 'ALL', 'HIGH'),
