(1084, 102, 'Hỗ trợ trợ giá cước vận chuyển cho nhà vườn vùng xa (Kỳ 84)', 'Ban tổ chức áp dụng chính sách trợ giá 100% chi phí luân chuyển nông sản từ Mộc Châu về Hà Nội. Kính gửi quý bà con nông dân và quý khách hàng cập nhật chi tiết tại cổng thông tin MarketLink.', 1, NOW(), 'GENERAL', 'CUSTOMER', 'NORMAL'),
(1085, 101, 'Tọa đàm: Nông nghiệp tuần hoàn và kết nối chuỗi giá trị (Kỳ 85)', 'Thân mời các chủ hộ nhà vườn và khách hàng thân thiết tham gia buổi chia sẻ trực tuyến vào tối Thứ 5 tuần này. Kính gửi quý bà con nông dân và quý khách hàng cập nhật chi tiết tại cổng thông tin MarketLink.', 1, NOW(), 'EVENT', 'ALL', 'HIGH'),
(1086, 102, 'Thông báo lịch mở phiên chợ đặc biệt cuối tuần (Kỳ 86)', 'Phiên chợ nông sản sạch sẽ tăng cường 20 gian hàng đặc sản Tây Bắc và Tây Nguyên phục vụ cư dân. Kính gửi quý bà con nông dân và quý khách hàng cập nhật chi tiết tại cổng thông tin MarketLink.', 1, NOW(), 'MAINTENANCE', 'CUSTOMER', 'NORMAL'),
