-- ============================================================================
-- SCRIPT SEED TOÀN DIỆN CSDL MARKETLINK: MỖI BẢNG TỐI THIỂU 100 BẢN GHI
-- Dữ liệu chuẩn xác, đúng chuẩn 3NF, bảo toàn toàn vẹn khóa ngoại 100%
-- ============================================================================

USE marketlink_db;

SET FOREIGN_KEY_CHECKS = 0;

-- 1. BẢNG roles (Đảm bảo đủ 100 bản ghi)
ON DUPLICATE KEY UPDATE `description` = VALUES(`description`);

-- 2. BẢNG categories (100 danh mục nông sản chi tiết)
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `description` = VALUES(`description`);

-- 3. BẢNG users (Thêm 100 Nông dân 1001..1100 và 100 Khách hàng 2001..2100)
ON DUPLICATE KEY UPDATE `full_name` = VALUES(`full_name`), `status` = VALUES(`status`), `kyc_status` = VALUES(`kyc_status`);

-- 4. BẢNG user_roles (Gán quyền chuẩn xác)
ON DUPLICATE KEY UPDATE `assigned_at` = VALUES(`assigned_at`);

-- 5. BẢNG farmer_profiles (100 hồ sơ nông dân sáp nhập)
ON DUPLICATE KEY UPDATE `stall_name` = VALUES(`stall_name`), `is_approved` = 1;

-- 6. BẢNG customer_profiles (100 hồ sơ khách hàng tiêu dùng)
ON DUPLICATE KEY UPDATE `default_address` = VALUES(`default_address`);

-- 7. BẢNG markets (100 phiên chợ nông sản khắp các tỉnh thành Việt Nam)
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `status` = 'ACTIVE';

-- 8. BẢNG market_schedules (100 lịch họp chợ cố định)
ON DUPLICATE KEY UPDATE `open_time` = VALUES(`open_time`), `close_time` = VALUES(`close_time`);

-- 9. BẢNG farmer_market_assignments (100 phân bổ gian hàng)
ON DUPLICATE KEY UPDATE `stall_number` = VALUES(`stall_number`), `status` = 'ACTIVE';

-- 10. BẢNG farmer_cutoff_settings (100 cấu hình chốt đơn trước mở chợ)
ON DUPLICATE KEY UPDATE `cutoff_hours_before` = VALUES(`cutoff_hours_before`);

-- 11. BẢNG pickup_time_slots (100 khung giờ nhận hàng tại sạp)
ON DUPLICATE KEY UPDATE `start_time` = VALUES(`start_time`), `max_orders_capacity` = VALUES(`max_orders_capacity`);

-- 12. BẢNG farmer_kyc_documents (100 hồ sơ CCCD & chứng nhận VietGAP)
ON DUPLICATE KEY UPDATE `document_number` = VALUES(`document_number`);

-- 13. BẢNG products (100 sản phẩm nông sản sạch đa dạng)
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `price` = VALUES(`price`), `status` = 'AVAILABLE';

-- 14. BẢNG weekly_stock_templates (100 mẫu kế hoạch luân chuyển kho hàng tuần)
ON DUPLICATE KEY UPDATE `recurring_quantity` = VALUES(`recurring_quantity`);

-- 15. BẢNG orders (100 đơn hàng đặt trước nông sản)
ON DUPLICATE KEY UPDATE `order_status` = VALUES(`order_status`), `total_amount` = VALUES(`total_amount`);

-- 16. BẢNG order_items (100 chi tiết sản phẩm theo đơn)
ON DUPLICATE KEY UPDATE `quantity` = VALUES(`quantity`), `subtotal` = VALUES(`subtotal`);

-- 17. BẢNG reviews (100 đánh giá trải nghiệm thực tế)
ON DUPLICATE KEY UPDATE `rating` = VALUES(`rating`), `comment` = VALUES(`comment`);

-- 18. BẢNG favorites (100 sở thích theo dõi gian hàng/sản phẩm)
ON DUPLICATE KEY UPDATE `target_type` = VALUES(`target_type`);

-- 19. BẢNG notifications (Thông báo sự kiện hệ thống)
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`);

-- 20. BẢNG system_announcements (100 thông báo chính sách & tin tức phiên chợ)
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `is_active` = 1;

-- 21. BẢNG family_account_invitations (100 lời mời liên kết ví gia đình)
ON DUPLICATE KEY UPDATE `status` = VALUES(`status`);

-- 22. BẢNG user_verifications (100 mã OTP xác minh tài khoản)
ON DUPLICATE KEY UPDATE `verification_code` = VALUES(`verification_code`), `is_used` = 1;

-- 23. BẢNG verification_audit_logs (100 nhật ký xét duyệt hồ sơ nông dân)
ON DUPLICATE KEY UPDATE `reason` = VALUES(`reason`);

SET FOREIGN_KEY_CHECKS = 1;

-- HOÀN TẤT SEED TOÀN BỘ 23 BẢNG CSDL MARKETLINK: MỖI BẢNG TỐI THIỂU 100 BẢN GHI
